-- Table: transaction_goods_receipt_detail
-- Source: accounting_admin_db.sql (4. Purchasing flow)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS transaction_goods_receipt_detail (
    id                       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    goods_receipt_id         BIGINT NOT NULL REFERENCES transaction_goods_receipt(id) ON DELETE CASCADE,
    line_number              INTEGER NOT NULL CHECK (line_number > 0),
    purchase_order_detail_id BIGINT REFERENCES transaction_purchase_order_detail(id),
    product_id               BIGINT NOT NULL REFERENCES masterdata_product(id),
    description              TEXT,
    quantity                 NUMERIC(18,4) NOT NULL CHECK (quantity > 0),
    uom_id                   BIGINT NOT NULL REFERENCES masterdata_uom(id),
    unit_cost                NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (unit_cost >= 0),
    weight_kg                NUMERIC(18,4) NOT NULL DEFAULT 0 CHECK (weight_kg >= 0),
    batch_number             VARCHAR(100),
    expiry_date              DATE,
    UNIQUE (goods_receipt_id, line_number)
);
